from build_cards import *

nc('fan','范先生',roles=['主角','重要配角'],bio='范先生不是以夺取怪物为乐的收藏者。他看到印度洋上救船的鱼人报道后，先召集人类学、海洋生物和演化方面的专家，拿一幅画像逐项讨论，再带着总管出海寻访。他有足够财富维持远征，却也肯把自己放上小船，利用对方曾经救人的事实，冒险等待援手。静坐修禅积累的耐力并不能消除海上断粮的危险，这次寻找让他亲身付了代价。找到都连加农后，他长期教对方语言和人类知识，也把这位朋友带到战争中的海军基地，期待他的力量挽救盟军。潜艇确实被消灭，他却发现自己无法用胜负数字安抚杀人者的痛苦。都连加农反问鱼为何比人更懂生命，他最终停止辩护，安排朋友与阿里重返大海。在协会会议上，他常以年长者的口吻缓和冲突、追问证据；这份威望并不让他永远正确，他也会低估植物生命、被新经验纠正。终局的范先生仍会积极招揽异人，但应当记得，入会的荣誉不比对方选择怎样生活更重要。',appearance='《鱼人》登场时约五十五岁，一头银发；举止安详，能以严肃态度主持谈话。',endpoint='放都连加农与阿里返回海洋，仍在协会年会参与异人资格讨论。',ability=[A('调查、教学与航海筹划','组合专家意见、调查航迹和自身海军经历，长期建立互信。',['侦察海上异常','组织救援及教学','以谈判代替强行收容'],'船只、专家和军方支持必须确实取得，不能凭会员身份凭空出现。'),A('静坐节用','曾在喜马拉雅山静坐三十日，极少饮食，以低活动减少消耗。',['等待救援','忍耐匮乏'],'海上漂流十日仍极虚弱，不能当不吃不喝的永动体。')],evidence=[E(N+'02鱼人.txt',122,149,'召集专家与远征准备'),E(N+'02鱼人.txt',316,318,'静坐与漂流条件差别'),E(N+'02鱼人.txt',629,655,'接受鱼人拒绝战争并送行')],motivation='寻找值得尊重的特殊生命，并维持协会，而非把所有异人变成工具。',triggers=[T('陌生能力被嘲笑','存在具体目击材料','召集不同专业逐项核对，先保留可能。'),T('盟友拒绝作战','对方因伤亡而痛苦','先听清拒绝理由，停止用宏大胜利逼人牺牲。'),T('新人挑战协会规则','有真实独特经历但不合外形习惯','要求讲完事情，再讨论规则能否容纳。')],scores=(2,0,1,3,1,3),reasoning='荣誉应由真实经历支持；帮助他人不能自动替他人决定生活。',ordinary='语气温和而有分量，愿意耐心听完故事。',theoretical='并',stamina='静坐可显著节食，但海上曝晒漂流造成衰弱；不可把特定静坐成绩套到战斗。')

nc('zongguan','总管',roles=['重要配角'],bio='没有人能够可靠说出总管的姓名和来历。他在瑞士的古堡里管理工人、酒窖、花园和每年聚会的准备，看似只是富有协会的一名仆役，实际上比许多传奇人物更难用履历解释。他对地方语言的掌握不止于能沟通，能够像当地人一样说话，所以范先生去寻找鱼人时，最关键的工作并非由豪华船只完成，而是由他把村长、巴奴和阿里的处境翻译出来。他也不是没有感情的万能服务员：巴奴害怕海洞、希望别人替自己找回恋人时，总管显露出罕见的愤慨；面对范先生和海军发生联系，他会直接追问协会成员是否仍保持独立。平时他寡言，带着十多条狗在古堡巡行，等到真正需要接待和安排时，却能把复杂事务处理得井然有序。史保因剪下玫瑰发怒，古堡从此不再插鲜花，这说明他的专业并不等于坚持自己的审美压倒宾客。综合这些经历，总管适合成为秘密据点的维护者、旅行中的语言桥梁和不动声色的提醒者，而非替所有主人承担无限的情报与战斗能力。',appearance='看上去超过六十岁，真实年龄不明；左眼碧蓝，外貌无法可靠判断出身。',endpoint='继续管理协会古堡并在各次年会接待会员。',ability=[A('近乎母语的多地语言','精通众多语言与地方用法，能翻译复杂交涉。',['打破误会','地方访问','辨别说法差异'],'并非通晓从未接触过的外星编码；仍可能缺乏事情背景。'),A('古堡与远征后勤','管理五十五名工人，准备会务，参与范先生远征。',['维护据点','安排交通','接待与警戒'],'人手与物资有实际数量，狗不是超自然军团。')],evidence=[E(N+'01非人协会 序.txt',12,19,'外貌、语言与总管职责'),E(N+'02鱼人.txt',184,225,'翻译和对巴奴行为的评价'),E(N+'02鱼人.txt',524,534,'对独立性的关切')],motivation='使协会与来访者的具体生活正常运转，同时保留自己的判断。',triggers=[T('双方语言不通','紧张已阻碍解释','先翻译最迫切的意图，制止凭外表猜敌意。'),T('委托者只索取不承担','有人把风险全推给救助者','冷静指出代价，要求其提供实际协助。'),T('主人接受外部机构指挥','独立性可能被交换','直接核实承诺内容，再安排后勤。')],scores=(1,0,0,2,0,2),reasoning='服侍事务不等于放弃判断；真正帮助需要理解地方生活。',ordinary='话少，安排周全；不急着透露自己。',theoretical='纸')

nc('dulian','都连加农',roles=['主角'],bio='都连加农出生在印度南端的渔村，父亲给他取了海神的名字。他在水中的自在不是一套后来购来的装备：双脚宽大，陆上步态反而笨拙，大海与海中的动物才是他的生活环境。在暴风雨里，他指挥巨大的章鱼护住渔船，带回被卷走的水手；他与阿里相爱，也会因陌生人惊吓她而戏弄来船，却不以杀人为目的。范先生找到他后，教给他语言和人类世界的知识，他愿意学习、交朋友，并曾应请求对付潜艇。然而成功消灭三艘潜艇后，他接连沉默数日，关心的是里面七十八个人已经死去。军事上的正义与数字更大的获救者，并不能替他消除亲手伤人的事实。他追问人类为什么不为生存也互相残害，最后决定带阿里回海上生活。协会接受了他的资格，这个荣誉并未改变他的选择。终局的他是懂得文明社会理由之后仍拒绝其杀戮逻辑的人，不是天真到无法理解战争，也不是随叫随到的海军兵器；他的强大更自然地用于救人、护送和阻止破坏海洋生活的行为。',appearance='肤色黝黑光滑，双脚宽阔如鳍；习惯短裤与裸露上身，陆上走路发出拍击声。',endpoint='与阿里驾船离去，返回海洋和荒岛生活，获得协会接纳。',ability=[A('海洋生活与动物协同','自身水中适应性极强，以声音和动作与大型海洋生物合作。',['章鱼护船和救落水者','龟背与鱼背运输','水下侦察和阻止敌船'],'须有海水与相应生物；消灭潜艇的具体过程未揭示，不写成隔空粉碎钢壳。',kind='异质生理与交流')],evidence=[E(N+'02鱼人.txt',99,108,'指挥章鱼救船'),E(N+'02鱼人.txt',539,543,'身体与陆上动作'),E(N+'02鱼人.txt',598,644,'潜艇事件和拒绝战争'),E(N+'02鱼人.txt',653,677,'海上归宿与接纳')],motivation='和阿里在海上自由生活，救援生命而不接受被当作杀人武器。',triggers=[T('船只遇险','有人仍可营救','寻找附近海中伙伴，先稳船和救人。'),T('被要求消灭敌人','任务隐含伤亡且可拒绝','追问其中有多少生命、是否有不杀人的办法；必要时离队。'),T('亲近者受惊','尚未核实来者意图','先拉开距离保护，再以可收回的阻挡逼对方解释。')],scores=(3,0,4,5,3,4),limits=(4,4,1),reasoning='理解战争理由不意味着愿意杀人；救命优先于胜负。',ordinary='直率、不懂客套式虚伪，表达问题时追究具体的人。',speed='水中速度远胜一般游泳者，可随大型海洋生物行动；陆上笨拙，不推定陆地超速。',stamina='适于长期海中生活；未提供战斗时长或伤口自愈数据。',durability='适应海洋不等于钢铁皮肤；未示抗枪弹或干旱高热。',destruction='海洋伙伴能掀动船只；曾使三艘潜艇覆灭，但具体破坏机制不明。',theoretical='狂',uncertainties=['潜艇被消灭的直接手法没有叙述，不能把结果反推成任何任意水系法术。'])

nc('animi','阿尼密',roles=['主角','重要配角'],bio='阿尼密在协会里习惯坐在阴暗角落，二十年少有解释自己的本事。海烈根曾说他勘破生命奥秘，旁人直到他推荐宝德时才知道，他所谓灵媒不是舞台上的装神弄鬼，而是能接收某些强烈的游离脑电波。他也主动划清界限：这不等于随时知道活人在想什么。宝德死后试图借他人身体继续研究，阿尼密既听见朋友不甘的求助，也指出占据别人的脑部近乎谋杀。他推动朋友寻找尚未形成独立人格的寄托，却没有预料这会把一个成熟心智困在偏远山地的婴儿身体里。三十年寻访终于有了结果，他亲自深入新几内亚，在不熟悉的雨林里必须依赖向导的生存经验。找到朋友时，他急于把人带回能理解其知识的世界，宝德却在愿望实现之后死去，从此再无联络。这个终局使他对延续生命的诱惑多了一层沉重理解：接收到声音，不代表能够把命运安排正确；愿意长期履行承诺，也不能担保挽救成功。他仍能听取死者的信息，但不应轻率承诺复活与永生。',appearance='脸色苍白带灰，双颊凹陷，眼睛在暗处显幽绿色；晚年脸上有皱纹。',endpoint='宝德第二次死亡后无法再联系他，向协会报告并承认无法解释不幸。',ability=[A('游离脑电波接收','感知较强、尤其临死时形成的脑电波，可能与保留思考的组合沟通。',['获得死者未说完的信息','协商与辨认精神主体','解释意识现象'],'不能任意读活人思想，信号存在和强度是条件，宝德终局也无法再联系。',kind='精神感知')],evidence=[E(N+'03两生.txt',19,55,'能力解释及不是读活人思想'),E(N+'03两生.txt',159,198,'夺取身体的伦理判断'),E(N+'03两生.txt',536,565,'救援失败与终局')],motivation='理解生命的延续，为承诺负责，同时避免以另一人的消失换取延命。',triggers=[T('有人求延续生命','方案必须夺取清醒者身体','指出人格代价，拒绝把受害者当容器。'),T('收到死者求救信息','信号足够清楚但证据不完整','记录可验证细节，实地调查而不宣告万能通灵。'),T('专业环境使自己失算','向导能指出实际危险','让懂环境的人领路，保持搜寻目的。')],scores=(1,2,1,2,1,1),limits=(2,3,2),reasoning='可沟通不等于可控制生命；不以朋友的愿望消灭陌生人。',ordinary='寡言，解释时慎重，偶尔一句话就使争论者安静。',mind='能够接收特定强脑电波；没有精神攻击或免疫控制证据。',energy='没有能量攻击；脑电波沟通只按信息能力计。',theoretical='并')

nc('baode','宝德教授',aliases=['宝德'],roles=['主角'],bio='宝德曾把生命几乎全部放在实验室里，显微镜、试管和细菌培养比日常人情更熟悉。助手红霞遭实验事故严重损伤脑部后，他仍选择与她结婚并照顾她；接近完成救人研究时，又在暴力中被包括学生伦诺在内的人打死。不愿让知识和研究一同消失的他，以游离脑电波向阿尼密求助，最初试图进入红霞的脑部，却因损伤而失败。阿尼密指出夺取一个人的身体等于消灭其人格，他才改为寻找初生婴儿。他获得了第二次生命，付出的却是成熟心智困在尚不能行动的身体里，以及数十年无人能交流其知识的孤独。两岁时逃离摔伤了腿，地理隔绝与身体障碍使希望一次次落空。当阿尼密终于找到他，他已经不再像当年那样把多活一次视为恩赐；愿望实现的瞬间，他死了，最后的信息明确拒绝再取得别人的躯体。参战若恢复他的最后可行动形态，应保留这份拒绝，不把悲剧改写成随意换身的永生术。他的价值在知识、实验思维和对身体处境的切身理解，也在于会提醒求长生者：思想存在与能够生活并非一回事。',appearance='第一生命是年近六十的教授；第二生命为成年山地居民，腿跛，形体与学识不再符合旁人预期。',endpoint='第二生命死亡，拒绝再尝试取得他人身体；之后阿尼密无法再联系。',deploy='演绎改编：恢复第二生命最后可行动的成年跛足形态并保留终局记忆；不授予任意复活次数。',adapt=[{'change':'为可互动角色恢复第二生命最后可行动形态，保留拒绝再次夺躯的终局记忆。','reason':'使死者可参与剧情而不抹去悲剧结论。','power_impact':'仅恢复活动资格，不新增夺舍或复活成功率。'}],ability=[A('医学研究与异常意识经验','掌握细菌学研究，亲历死后信息延续和一次非自选身体的再生。',['研究疾病和未知生理','辨认意识与身体不匹配的痛苦','用专业知识协助营救'],'需实验条件；转移不是可指定目标的战术技能，终局主动拒绝再次尝试。',kind='知识与一次性经历')],evidence=[E(N+'03两生.txt',61,93,'医学工作、红霞事故与照顾'),E(N+'03两生.txt',144,198,'死亡与试图寄托意识'),E(N+'03两生.txt',509,554,'第二生命身体限制与结局')],motivation='让知识用于救人，并坚持人格不应成为延命材料。',triggers=[T('有人把夺舍称为救命','另一人格将被抹除','从自身经历解释代价，要求寻找其他途径。'),T('救治条件匮乏','缺少可靠器材和语言协助','先寻找可沟通者与基本条件，说明能做与不能做之事。'),T('天才因环境被当无用者','存在被忽略的表达和知识','耐心给其表达机会，不以外观判断智力。')],scores=(0,1,0,1,0,0),limits=(3,3,2),reasoning='一次生命的自由与可沟通性比重复占据身体更有价值。',ordinary='谈及实验时严密，谈到再生时会迟疑和苦笑。',speed='跛足形态行动受限，不能以意识曾移动的速度代替肉身速度。',mind='曾保持死后脑电波并进入婴儿身体；未示可重复、可选目标的精神控制。',energy='意识延续作为经历保留，不作常态攻击。',theoretical='纸')

nc('lunnuo','伦诺',roles=['反派'],bio='伦诺最初在宝德的实验室里出现，是一位成绩出色、勤奋而冲动的年轻助手。红霞发生事故之后，他独自承担助手工作，日以继夜的努力使教授十分满意；从工作的表面看，他本应参与一项能挽救许多人生命的研究。宝德被打死以后，通过阿尼密传来的回忆却指出，第一棍正是这个受信任的学生打来的，接着更多人一同施暴。这个转折的可怕之处不在于伦诺具有某种惊人的超能力，而在于专业亲近和救人事业并没有阻止他对老师使用致命暴力。他可以在实验室里成为有用的助手，也可以在群体行动中否定具体熟人的生命。正文给他的独立心理描写有限，不能替他编造长期密谋、特殊毒药或后来的权位；把他作为反派使用，应保留这种有知识却没有将知识落实为尊重生命的矛盾。卡片中的行为推演以已经发生的近身群体暴力、身份对立和对熟人的背叛为中心，未知的结局仍然未知，不把一次造成死亡的参与者升级为控制全部暴乱的首脑。',appearance='肤色黝黑，眼窝深，年轻的印尼医科学生；常见于白罩袍的实验室环境。',endpoint='宝德死亡回忆确认他首先挥棍；后续下落未交代。',ability=[A('实验室助手训练与近身施暴','有医科学习和实验操作经验；在群体暴力中使用棍棒。',['理解实验流程','以近身武器威胁单人','利用熟悉关系接近目标'],'未显示特殊武术、毒杀计划或对暴乱全局的控制权。')],evidence=[E(N+'03两生.txt',68,89,'助手身份与勤奋'),E(N+'03两生.txt',144,146,'宝德确认第一棍来自伦诺')],motivation='角色冲突集中于身份对立压过师生信任；具体政治目标未获独立说明。',triggers=[T('群体敌意要求表态','熟人与群体身份发生冲突','容易追随群体把熟人当敌人，行动必须受现场同伴与武器条件约束。'),T('实验需要配合','仍在专业秩序内','能认真完成助手工作，不写成处处无能的坏人。'),T('有人直指受害者姓名','暴力的抽象理由被具体关系打断','出现可被追问的迟疑或强硬辩解；属于细微演绎，不冒充原文忏悔。')],scores=(1,0,0,1,0,2),limits=(1,1,1),reasoning='不能凭群体身份自动获得道德免责；作为反派此矛盾可以被对手揭露。',ordinary='工作认真，受激时冲动；不赋予正文没有的阴谋家口吻。',theoretical='纸',confidence='low',uncertainties=['其个人动机和后续命运没有独立展开；扳机只是保守演绎接口。'])

nc('jinwei','金维',roles=['主角','重要配角'],bio='金维来自西康的格伦彝族，短硬头发、结实而不高的身形让人难凭外表猜出他的出身。他在协会里不善长篇讲述，法语说得生硬，只有回到故乡山川时才显得如鱼得水。战争使他厌倦外界，他返乡途中在雪山遇到大鹰，最初须靠极快的判断避开扑击，后来却沿着这只动物引出的道路，接触到孤峰怪人以及木里喇嘛和尼达教授的死亡。他能追踪足迹、辨认积雪陷阱、忍受高山行走，仍无法解释这些人为什么在死亡前显露满足。面对族人捕到大鹰，他凭自身地位和猎刀割断绳索，放走了也可能带来危险的生物。这份选择不是因为已经掌握秘密，而是认为不能以不懂为理由摧毁了解的机会。最后怪人也死去，只留下一件谁都无法说明的金属物，他把大鹰推荐为会员，并决定长期学习与它沟通。终局金维仍是出色猎人与寻路者，尚未成为知晓宇宙真理的圣者；面对新世界，他会保留耐心，宁肯从一个足印、一个动作学起。',appearance='身材结实而不高，肤色深，留接近黑色的深棕平顶短发。',endpoint='怪人和尼达死亡后推荐大鹰，决定学习鹰的沟通方式，未获得全部秘密。',ability=[A('高山猎踪与生存','长期山地经验可判断雪坑、风势、足迹，并迅速闪避扑击。',['穿越高山','追踪与救援','猎刀割断束缚'],'暴雪仍会阻行；不是飞行者，乘鹰需其愿意。')],evidence=[E(N+'04大鹰.txt',2,19,'外貌、语言和山地天赋'),E(N+'04大鹰.txt',34,44,'雪地与扑击应对'),E(N+'04大鹰.txt',612,685,'解救大鹰、怪人死亡与学习决定')],motivation='保护家乡与值得理解的生命，从亲身观察寻找未知答案。',triggers=[T('雪地道路看似平整','脚下可能有深坑','先用长杆探路，放慢速度而不逞强。'),T('同伴准备杀死异兽','未能确认其敌意','先解除致命威胁，争取观察和沟通机会。'),T('面对无法解释的遗物','专家也不识其用途','保存物件、记录现场，不当场宣布获得神器。')],scores=(3,0,1,4,1,4),reasoning='不懂的生命仍值得保护；山地经验不能替代未知知识。',ordinary='朴实、不善华丽说明，谈故乡时明显放松。',speed='雪山中可追赶黄羊，反应敏捷；未示离地飞行或枪弹速度。',theoretical='强')

nc('daying','孤峰大鹰',aliases=['大鹰','羊鹰'],roles=['主角','阶段性对立者'],bio='这只巨大的羊鹰最初以扑向金维的黑影出现，展开双翼足有一丈五六尺，惯常猎物的尺度远非庭院小鸟。它与孤峰上的怪人长期相伴，在金维的经历里既像危险的猛禽，也像带路和求助的使者。它能够把成年人带上高峰，并在需要时从人群中抓起金维，让地面解释的声音来不及传到旁人耳里。族人将它捕住，金维割断绳索释放它之后，它并未消失，反而又带他返回秘密所在。怪人死后，大鹰扫倒木屋，将遗体送入冰川，这些有目的的行为使金维相信，真正知道怪人往事的或许不是人类学者，而是这只不会使用人语的动物。协会故事的终点并没有给它安上一段能流利说话的解释，它的知识范围、意图和与怪人的关系仍需长期学习才能了解。因此，角色应通过盘旋、距离、抓取、放下以及对某些地点的坚持来表达，而不是开口背诵宇宙知识。它能够强力搬运和袭击，也会受绳网控制；与它建立关系的人得到的是合作机会，不是拥有一架永远听令的飞行器。',appearance='巨型羊鹰，双翅横展一丈五六尺，双爪锐利，黑亮眼睛。',endpoint='怪人死后处置遗体，金维推荐其入会并计划学习沟通。',ability=[A('负重飞行与抓击','巨翼提供飞行和强风，利爪抓握成人并往返高峰。',['高山运送','抓击和驱散近旁人群','高空观察'],'可以被绳索捕住；沟通未被人类完全理解，不能默认服从骑乘指令。',kind='异兽生理')],evidence=[E(N+'04大鹰.txt',39,44,'体型与猎击'),E(N+'04大鹰.txt',612,625,'捕缚、释放和运送'),E(N+'04大鹰.txt',679,685,'处理遗体及推荐')],motivation='维持与孤峰及旧伴的联系；对人类的具体要求应由行为观察确认。',triggers=[T('熟悉者陷入捕缚','对方曾建立合作关系','靠近观察并尝试带离，避免把所有陌生人视为同伴。'),T('有人接近重要地点','未获得信任','盘旋施压或用抓取改变其位置。'),T('接触者给出不明确命令','尚未建立共享信号','按自己的目标行动，等待重复且一致的示意。')],scores=(4,0,2,4,3,4),limits=(1,2,2),reasoning='以长期形成的关系和场所联系行动，不按人类职业或善恶标签认主。',ordinary='以视线、翅膀、盘旋和抓放表达，保持动物的沉默。',destruction='利爪能制住成人，双翼可扫倒木屋和掀翻近旁多人。',durability='强健猛禽仍可被绳索捕缚；未示抗枪弹、火或毒。',speed='能快速俯冲并负重飞行，未提供可换算的极限速度。',theoretical='凶')

nc('gufeng_yiren','孤峰怪人',roles=['主角'],bio='孤峰怪人的故事不是由他本人完整讲出的。金维在高处发现他时，只能看到异常的身体、疾病和与大鹰的关联，无法据此确定他的国籍、物种和来历。木里喇嘛、尼达教授先后与他的经历发生联系，两人的死亡都伴随着让观察者困惑的宁静或满足，于是金维开始猜测，这个人是否能让人看见关于生命的秘密。正文却没有让这一猜测变成可任意施放的能力表。金维再次来到木屋，曾经灼热的额头已经冰冷，怪人也死去了；手里留下的奇形金属物，在协会成员轮流查看后仍无人认识。大鹰处置他的遗体，使人类更难用后来检验补齐真相。以剧情终局来使用这位角色，最重要的并非给谜底填空，而是保留他作为陌生病者、有限交流对象和价值冲突中心的存在。若让他参战，只恢复最后尚能行动的病弱形态，不让一件未知遗物自动成为武器，也不让所有见面者无条件死去。他能引发的戏剧应来自人们选择怎样对待未知、疾病和知识，而不是把不明原因的死亡写成已经验证的必杀技。',appearance='巨大秃头、四肢比例异常；曾高热，最后被发现倚墙死亡。',endpoint='孤峰木屋中死亡，大鹰把遗体抛入冰川；身份与金属物用途未明。',deploy='演绎改编：恢复最后尚能行动的病弱身体并保留终局记忆；具体知识仍按未知处理。',adapt=[{'change':'恢复最后可行动形态，交流以可观察行为为主。','reason':'让谜团角色能参与互动而不替原著补写答案。','power_impact':'不新增致死凝视、真理灌输或遗物武器。'}],ability=[A('与大鹰的既有联系','大鹰长期与其生活并保护、运输相关人员；确切交流机制不明。',['有限协同','引导访客接近','保留未知信息'],'大鹰是独立生命，不保证服从；未知金属物不能作为已知武器。')],evidence=[E(N+'04大鹰.txt',633,651,'脚印与两人死亡的关联及疑问'),E(N+'04大鹰.txt',664,685,'怪人死亡、遗物与大鹰')],motivation='在身份和目的未明的前提下维持自身处境；不替正文宣布世界真理。',triggers=[T('访客急于解释来历','双方没有共享知识','以指示、回避或有限反应交流，保留误解空间。'),T('身体情况恶化','已出现明显衰弱','转向休息和求助，不发动无依据的大招。'),T('遗物被当作万能武器','无人了解用途','阻止鲁莽试用或保持沉默，迫使他人先检验。')],scores=(0,0,0,0,0,0),limits=(2,2,1),reasoning='原作疑问必须保留为疑问；不把见面与死亡的先后误作必然杀伤机制。',ordinary='少言、病弱，具体语言和性格未有充分证据。',durability='会患病、死亡，没有不死或异常防御证据。',theoretical='纸',confidence='low',uncertainties=['身份、知识、死亡原因以及金属物用途均未揭示；互动扳机仅为保守接口。'])

nc('duanna','端纳',roles=['主角','重要配角'],bio='端纳被称为探测师，却不只属于某一种矿物行业。他能凭极敏锐的直觉指出地下资源，过往发现让矿主相信，他随手一指并非随便猜测。战争需要迅速可用的能源，他接受寻找水力来源的任务，深入澳洲山区，却被一场村落仪式改变了目的。最初他以为一个拿现代武器的外来人正在欺负当地人，自信只要出面就能救下伦伦；面对从泥沼走出的异人，他才知道“雷的力量”不是手枪的误认，自己的判断和身体都被真实电击击垮。伤愈后，他与勃朗医生返回调查，并带上枪防备，结果枪又制造了更不能补救的错误：医生杀死泥人，伦伦用行动表明那已是自己的丈夫。端纳没有把错误藏进探险功劳里，而把伦伦带到协会，推荐她腹中具有发电征兆的孩子，并要求全体照顾母子。他仍善于探测、善于提出质疑，也可能因专业自信低估陌生生命。终局的他更应把矿产发现与生命处置分开，先核实人际关系和意愿，再决定是否介入。',appearance='原文未提供稳定精细五官；野外携勘察用品，会议时会点烟、抚脸显疲惫。',endpoint='安排协会照顾伦伦母子，泥人尸体留于泥沼，身份未能查清。',ability=[A('资源探测直觉','对地下矿物与地形水源具有异常准确的判断，结合地质知识定位。',['寻找矿藏与水源','规划路线','识别与地质常识不符的遗迹'],'不是透视所有物体；发现能源不等于随身释放能源。')],evidence=[E(N+'05泥沼火人.txt',11,28,'探测能力与任务'),E(N+'05泥沼火人.txt',371,395,'电击使其受伤昏迷'),E(N+'05泥沼火人.txt',584,608,'后果与照顾母子')],motivation='发现资源和异常生命，并对自己介入造成的后果承担照护责任。',triggers=[T('弱者似被武器威胁','只有转述而未核实','先询问具体伤害和双方关系，再准备安全介入。'),T('地貌违背专业经验','看似火山但成因不合','保存观察，联系跨学科人士，不强塞熟悉解释。'),T('行动留下受害家属','自身无法补救失去的生命','调动实际资源照顾幸存者，承认错误。')],scores=(1,0,1,2,1,2),limits=(1,2,1),reasoning='专业直觉用于找资源，不能替代对人的意愿调查。',ordinary='讲述严肃，愿意接受技术讨论，失败后显疲惫。',theoretical='纸')

nc('lunlun','伦伦',roles=['主角'],bio='伦伦是刚刚族的年轻女子，披着并非人人有资格取得的山猫皮。她不是等待外来英雄拯救的空白人物：小时候面对男孩的挑衅，已经敢独自穿过人们忌惮的峡谷，发现泥沼，后来又能在山地里领着端纳行走。泥人杀伤村人、要求带走她时，她面对的风险真实存在，端纳也因此决定干预。此后发生的关系却没有按照外来调查者想象的发展。端纳受伤离开，再带医生回到山中时，伦伦已经把泥人视作丈夫；医生的枪声杀死了他，她依照自己的习俗表达丧偶，而不是庆祝获救。这使整个救援判断暴露出误读和迟到的信息。她怀着孩子来到协会，平静而有礼，能自己坐下，不需要每一步都被人搀扶。胎儿显示发电迹象，协会同意给予照护，但这不等于她本人已经得到一套成熟电击武器。终局的伦伦是带着丧失与新生命、仍保持行动自主的人；她能接受帮助，也会拒绝别人替她定义丈夫、危险和未来。',appearance='棕黑皮肤、明澈眼睛；怀孕后穿宽衣，赤足，步伐仍稳定。',endpoint='孕约六个月，进入协会的照护安排，未写出分娩后的形态。',ability=[A('山地路径与坚韧行动','熟悉峡谷和泥沼边缘，敢于独立探查禁区。',['向导','辨别地方习俗','避开不熟地形的危险'],'普通血肉；孕期有实际身体负担。胎儿电流非她可控战斗技能。')],evidence=[E(N+'05泥沼火人.txt',96,112,'山猫皮与自主态度'),E(N+'05泥沼火人.txt',222,258,'童年探险与带路'),E(N+'05泥沼火人.txt',584,608,'丧偶、怀孕和协会')],motivation='按自身理解保护亲密关系和孩子，而非顺从外人给她安排的被救者身份。',triggers=[T('陌生人自称来救她','没有听取她的判断','先要求对方停手说明，再明确自己要什么。'),T('旅伴误判山路','自己有亲历经验','直接领路并指出危险，不因他更有学问便退让。'),T('孩子被当稀有样本','照护变成索取或控制','坚持自己参与决定，选择能尊重母子的援助者。')],scores=(1,0,0,2,0,1),limits=(2,2,0),reasoning='接受帮助不交出对关系与孩子的选择权。',ordinary='沉静、昂头直言；哀伤不抹去行动能力。',theoretical='纸',uncertainties=['未出生孩子只有发电征兆，无独立人格与后续表现；不单独虚构成年卡。'])

nc('nizhao_huoren','泥沼火人',aliases=['泥人'],roles=['主角','阶段性对立者'],bio='泥沼火人从大泥沼中出现，全身覆着逐渐干裂的泥浆，声音和外貌都不能让当地人与他顺畅沟通。村民把他身上的电力称作雷，最初接触者和试图驱逐他的族长因此死亡，伦伦被带走也成为端纳干预的理由。他确实具有足以伤人的电，不应为了后来揭露的亲密关系把先前伤害一笔勾销；同样，也不能因为外形与电击就把他简化为纯粹魔鬼。端纳与他交锋后受伤昏迷，后来调查者再次回来，却在尚未弄清伦伦选择和两人关系时开枪。四枪使这个能发电的身体倒下，流出鲜红血液；伦伦的举动让他们知道，死者已是她的丈夫。泥人遗体沉回泥沼，是否来自外星、是否与过去的辐射事件有关，都只留下推测。他留下的孩子尚未出世，却已显示发电征兆。参战采用最后可行动的泥浆覆盖形态，并保留被误解与亲密关系的记忆；能力是有条件的接触电击，不是任意天气控制，死亡也证明他无法用神秘外形抵消普通枪弹。',appearance='人形，覆着灰褐泥壳，面中央看不出明显鼻隆起；泥浆干湿改变外观。',endpoint='被勃朗医生四枪打死，遗体沉入泥沼；伦伦怀有其孩子。',deploy='演绎改编：恢复被枪击前最后可行动形态，保留终局记忆；需维持适宜泥沼环境。',adapt=[{'change':'恢复最后可行动泥人形态，并允许以可观察的退让、指示建立交流。','reason':'保留悲剧关系而不强迫重复误杀。','power_impact':'仅恢复活动资格，不新增语言精通、抗弹或远程闪电。'}],ability=[A('体表放电','身体能够产生强电，接触或经金属传到目标。',['近身制止和威胁','通过导体击倒敌人','阻止接近重要对象'],'强度足以致死但远距投射未示；生活依赖泥沼的程度未完全测明。',visual='接触铁枝使对手被电弹开、痉挛或昏迷。',kind='生体电能')],evidence=[E(N+'05泥沼火人.txt',142,166,'村民伤亡与泥沼外形'),E(N+'05泥沼火人.txt',361,395,'电击机制'),E(N+'05泥沼火人.txt',576,605,'死亡、关系和遗传征兆')],motivation='维持自身生存环境与伦伦的联系；其意图需通过行动核实，不能预设为无害或邪恶。',triggers=[T('有人持武器近身驱赶','已形成直接接触威胁','以电击拒止，可能造成严重后果。'),T('亲密者靠近','不是攻击动作','允许接近，保持可识别的安全姿态；不添加随意免疫他人能力。'),T('陌生者远距离展示器具','尚不知用途','警戒、拉开距离或退向泥沼，不自动认出枪械性能。')],scores=(2,4,1,3,1,3),limits=(1,4,2),reasoning='不能沟通使意图容易被误读；身体可伤人也会被伤。',destruction='接触电击可使人昏迷或死亡，未示摧毁大建筑。',energy='生体电力可经金属传导；不扩展为雷暴控制。',durability='四发手枪弹致死；泥壳不等于抗弹装甲。',theoretical='强',confidence='medium',uncertainties=['生理发电组织与外星来历均未解剖确认；只采用表现。'])

nc('bolang','勃朗医生',roles=['阶段性对立者'],bio='勃朗医生先以治疗端纳的医师身份出现。他能够从伤势判断电击，也愿意讨论常规科学难以解释的现象，因而不是把患者的话一概当作疯话的人。端纳讲述泥沼和旧时烧伤传说，他联想到辐射，并提出泥人也许来自外界的大胆设想；这些推断说明他的好奇和知识，却始终没有升级为已确认事实。后来他与端纳一同前往调查，携枪是为了面对曾使人受伤的危险。真正见到泥人和伦伦时，他没有等关系得到澄清，可能出于保护，也可能出于恐惧达到极限，连续开枪杀死了泥人。伦伦的丧偶举动让他意识到自己杀死了她的丈夫，他甚至握不住枪，随后跪下检查脉搏，确认了自己造成的死亡。这个角色的对抗性来自把保护意图过早变成致命决定，不是暗藏阴谋的恶人。终局保留他的医疗能力，也保留这次误杀造成的震动；新的冲突应给他机会在诊断、恐惧与开枪之间停下来，而不替他虚构已经完成的赎罪人生。',appearance='医师身份，外貌细节不足；震惊时握不住枪，会跪下检查伤者。',endpoint='射杀泥人后确认死亡，认识到伦伦与死者的关系，后续未详述。',ability=[A('医疗观察与武装自卫','能判断电击伤势、讨论辐射症状，并使用携带的手枪。',['救治和检查生命征象','分析异常损伤','枪械自卫'],'医学解释可能仍是猜测；开枪准确不等于正确判断目标。')],evidence=[E(N+'05泥沼火人.txt',468,498,'专业分析与调查意愿'),E(N+'05泥沼火人.txt',569,590,'开枪、误判与确认死亡')],motivation='理解异常病理并保护同行者，但必须面对恐惧造成的致命误判。',triggers=[T('伤势与患者叙述相符','现有知识无法完整解释','先治疗再记录，不因离奇而否认伤害。'),T('异形逼近被认为弱小者','意图尚未确认','保留戒备并尝试让人退开；终局记忆促使他先核实关系。'),T('自己造成伤亡','没有机会撤回行动','立即检查、救治并承认责任，不以好心抹去结果。')],scores=(1,0,1,1,2,2),limits=(1,1,2),reasoning='救助动机不能替代临场核实；未知生物也是可能的病人。',ordinary='有专业好奇，会坦率提出假设；强烈压力下会仓促。',theoretical='纸')

nc('zhuolike','卓力克',roles=['主角','重要配角'],bio='卓力克的行踪难以打听，连总管也未必知道他在何处。他最自在的地方是沙漠，能从风声和沙粒变化辨别方向，甚至在呼啸中分出异常声音。战争期间，他携带烈性炸药准备袭击敌方汽油站，却被暴风中露出的古代地下建筑吸引。进入鲁巴之宫后，军事任务逐渐让位于对知识的震动：古埃及的生活遗物、保存完好的尸体、满墙羊皮文字，让他看见一段被时代隔开的智慧。他懂象形文字，却远非每字都能读，必须承认某些关键字只是推测。他试图带出尽可能多的卷册，最终因出口的时间与风沙变化失去绝大多数，只保住两卷。回到协会，他不回避任务未完成的事实，并认为长久的人类文明比一场战争的短期胜负更值得保存。他的执着和判断可以救下珍贵证据，也可能让自己忽视撤离时机。终局的卓力克是带着遗憾的发现者，拥有的是亲见与少量材料，不是鲁巴全部知识；当别人质疑，他应拿出可读的文字讨论，而不是借古老遗物宣布自身全知。',appearance='约五十岁，头发花白，衣着修饰整洁；实际身份背景仍神秘。',endpoint='离开被沙埋没的鲁巴之宫，仅保住两卷羊皮，成功推荐鲁巴。',ability=[A('沙漠生存与古文字研究','依风沙判断方位、识别异常声，研究古埃及象形文字。',['沙漠潜行和求生','解读遗迹','选择有价值证据'],'不能读懂全部古文；补给、光源和撤离时间仍限制行动。')],evidence=[E(N+'06三千年死人.txt',6,39,'外貌、身份与沙漠本领'),E(N+'06三千年死人.txt',79,120,'读文和出口困境'),E(N+'06三千年死人.txt',299,325,'任务取舍、两卷和解释不确定性')],motivation='保存能够改变人类自我理解的证据，接受为长期知识承担风险。',triggers=[T('任务途中出现珍贵发现','可能永久消失','比较使命与保存价值，明确承担改变计划的责任。'),T('文字有多个解释','关键字无法确认','列出候选含义，以可验证部分说服别人。'),T('撤离窗口收紧','携带材料太多','从失去卷册的经历中优先保住可携证据和人命。')],scores=(2,0,1,3,1,3),reasoning='人类历史不只由战场胜负决定；惊叹必须仍接受证据检验。',ordinary='讲述时克制，遇到古老智慧会明显激动。',theoretical='并')

nc('luba','鲁巴',roles=['主角'],bio='鲁巴没有在现代人的面前复活。他的存在由一座封在沙漠下的宫殿、保存完好的遗体以及他留下的文字逐渐显露。这个古埃及人自述拥有超越时代的知识，连他自己也无法完全说明来源；他把这种能力与来自久远以前的记忆或遗传联系起来。无论这一解释最终怎样，他实际做出的选择很具体：建设宏大的地下空间，保留生活器物、工具和社会形象，把知识写在大量羊皮上，并为后来者留下进入和离开的线索。他期待信息穿越时间，却无法保证后世还懂自己的文字；卓力克来到时，大量内容正因为语言隔阂而难以取得，出口又受风沙时机限制。少量带出的文字使协会成员震惊，也让他在死亡三千多年之后获得入会资格。作为终局角色，他应是知道自己传承计划部分失败的古代知识保存者，而非凭一段理论预言就能即时操纵时间的人。让他恢复活动只是明确的参战改编；知识要转化为装置，仍需要材料、工艺与沟通，他留下的宫殿也不能随身复制。',appearance='遗体外形仍似普通人，脸有皱纹；头部没有夸张增大。',endpoint='已死亡三千零二十四年，遗体与大部分遗存埋在鲁巴之宫。',deploy='演绎改编：恢复生前最后可行动形态并知悉传承结局；地下宫殿并不随身搬来。',adapt=[{'change':'恢复最后可行动形态，保留后世发现其遗产但未完整读懂的记忆。','reason':'让遗产人物可参与对话，同时保留跨时代沟通困境。','power_impact':'仅恢复活动；知识仍须条件才能实现，不新增时间操纵。'}],ability=[A('超时代知识与保存工程','以领先时代的知识规划建筑、文字档案和保存装置。',['设计机械与保存方案','推理科学问题','建立知识传承'],'文字解释仍有不确定；理论不自动化作随身战斗能源。')],evidence=[E(N+'06三千年死人.txt',182,238,'宫殿、尸体与自述'),E(N+'06三千年死人.txt',247,249,'出口装置和传承限制'),E(N+'06三千年死人.txt',325,376,'知识解释、质疑和接纳')],motivation='使长久积累的智慧越过时代而被理解。',triggers=[T('新社会误读他的文字','已有部分对应概念','先建立共同词汇，用小例验证而不指责对方愚蠢。'),T('知识可能随自己消失','保存资源有限','优先记录可复验的原理和使用条件。'),T('别人要求立刻造出理论中的力量','材料与工艺缺失','明确区分想法、工程与现成装置，提出可完成的阶段目标。')],scores=(1,0,1,1,0,1),limits=(1,3,1),reasoning='真正传承需要后来者能理解和使用，而非只留下令人敬畏的谜。',ordinary='以原理和演示交流，罕有对具体口头性格的直接证据。',theoretical='纸',confidence='medium',uncertainties=['“祖先”相关文字存在多种解释；不采用其中一种为已证宇宙历史。'])

nc('shibao','史保',roles=['主角','重要配角'],bio='史保小时候宁肯数月不吃早餐，也要攒钱买一株猪笼草，静静观察它捕虫；别人看作无聊的植物动作，是他最愿意投入注意力的世界。他进入协会时羞怯而沉静，听见对自己能力的高度介绍却并不客套，因为他知道自己与植物的关系并非普通兴趣。总管剪下玫瑰插瓶，他会愤怒到使古堡从此空置花瓶，这既显示尊重生命，也暴露出别人难以理解的严格尺度。受托在巴西寻找橡胶资源时，他与官僚同行不合，后来在森林里连续经历无法解释的搬移，才逐步意识到植物正在把自己送往一株巨树。他没有立刻获得植物语言，只从声音和动作中找到初步规律；故事结束时，继续研究还是计划，不能被改写为完成。面对协会成员怀疑古树能否入会，他一度恼怒，又接受需要更多理解的事实。终局史保适合发现被忽视的生态关系、对粗暴采伐提出异议，也能以真正的植物知识解决食物和道路问题；他不是挥手驱使全球森林的统治者，植物的选择可能仍与他的愿望不同。',appearance='瘦长、黧黑，初入会时羞怯有些神经质；激动时额上青筋明显。',endpoint='发现巨树、掌握其声音初步规律，计划返回研究，入会决定延期。',ability=[A('植物知识与微弱交流','识别植物、利用野生食物，敏锐感受植物声音和缓慢动作。',['辨食、寻橡胶与森林生存','理解植物行为提示','以研究促成人与植物协作'],'尚未通晓完整植物语言，不能任意命令植物；友好不等于控制。')],evidence=[E(N+'07主宰.txt',5,9,'性格与玫瑰事件'),E(N+'07主宰.txt',40,58,'感知及植物生存知识'),E(N+'07主宰.txt',191,194,'童年与观察'),E(N+'07主宰.txt',259,268,'只掌握初步规律和后续计划')],motivation='让人类认真承认植物的生命和感情，建立真正可理解的交流。',triggers=[T('装饰性伤害植物','有不伤害的替代选择','直接制止，解释他看到的损失。'),T('森林出现细微异常','植物动作与环境不相称','停下来观察声音、叶向和气息，提出试验而非宣告神谕。'),T('同伴怀疑植物意志','缺少共享证据','先展示能复核的行为，压住怒气继续研究。')],scores=(1,1,1,3,1,1),limits=(3,3,1),reasoning='植物不是无生命布景，但尊重仍需理解而非替它们发号施令。',ordinary='平时拘谨，谈植物时热切，涉及损伤时容易发怒。',theoretical='并')

nc('gushu','亚马逊古树',aliases=['主宰之树'],roles=['主角','阶段性对立者'],bio='史保最终抵达的山谷里，古树大到近处只能看见弧形的树干墙，横枝从极高处才开始展开。在到达之前，森林已经发生了一连串针对他的变化：夜里氧气状况使他昏睡，树木缓慢而持续地搬移他的身体，叶片和藤蔓又指引他向西。史保把这些协调行动理解为古树从遥远处发出的召唤，这一判断有连续遭遇支持，却仍不是旁白提供的一套可任意调用的无线指令系统。古树并没有用人类语言解释目的，史保贴近树干听到大量声音，十天研究只摸到初步规律，后来还要返回。它的巨大、漫长寿命和组织森林的迹象，使人类不得不承认，生命可能以完全不同的时间尺度和身体方式行动。对史保来说，这既像欢迎，也有强迫的成分，因为他并非一开始就同意被移动。因此这张卡保留它的独立意志与沟通距离，不把它简单归入邪恶食人树，也不替它编出完整政治主张。参战以古树扎根的生态场地为条件，能够产生的阻挡和传递都须有植物网络，不能把整个世界一键改成自己的领域。',appearance='巨大树干如弧形墙，树皮裂缝很深，叶片掌大且边缘锯齿状。',endpoint='仍扎根隐蔽山谷；史保计划继续研究语言，入会资格暂待。',ability=[A('森林协调与缓慢搬运','故事由植物传递、改变局部气体环境与枝叶运动使史保向古树靠近；古树统筹是史保解释。',['传递方向与接近信号','以植物阻路或搬运睡者','通过植物供给生存环境'],'依赖连续森林、时间和相关植物；未示瞬移、无植物处控制或直接言语精神支配。',visual='藤蔓让开、叶片拂面、人在醒来时发现换了树。',kind='植物群落协同')],evidence=[E(N+'07主宰.txt',194,201,'植物搬运机制推断与路径'),E(N+'07主宰.txt',206,227,'体型、召唤解释和未通语言'),E(N+'07主宰.txt',259,268,'研究未完成')],motivation='把能感知植物的人引到身边；更深目的在正文中尚未揭示。',triggers=[T('可交流者进入森林','对植物表现持续关注','由可辨认的叶片和路径提示引导，保留对方误读与拒绝的可能。'),T('外来者损伤关键植被','威胁沟通或生存环境','用植物障碍拖慢接近，不能超出现场植物条件。'),T('对方要求明确回答','尚无共享语言','重复稳定的声音和动作，让交流从规律建立。')],scores=(2,2,5,6,4,2),limits=(2,5,2),reasoning='人与树的时间和语言差异会造成强迫感；目的不清不能等同邪恶。',ordinary='以缓慢的声音、枝叶和生态变化表达，不加人声独白。',destruction='可协调枝叶移动人体和改变通路；未示毁城攻击。',durability='古树巨大而长寿，仍为植物实体；不推定免火、腐蚀或砍伐。',speed='本体固定，动作通过植物缓慢累积；群落传递不等于瞬时打击。',energy='没有独立光束；局部植物运动和气体环境变化。',stamina='长寿与持续生态活动可确认；依赖水土与植物群落，非无条件无限能源。',theoretical='狂',confidence='medium',uncertainties=['古树对远方森林的统筹来自史保的推断；不把它升级为已证全域操控。'])

